      "name": "Derivation.apply_aeval_eq",
      "module_name": "Mathlib.RingTheory.Derivation.MapCoeffs",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_2} [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : Algebra R A] {B : Type u_4}\n  {M' : Type u_5} [inst_3 : CommRing B] [inst_4 : Algebra R B] [inst_5 : Algebra A B] [inst_6 : AddCommGroup M']\n  [inst_7 : Module B M'] [inst_8 : Module R M'] [inst_9 : Module A M'] [inst_10 : IsScalarTower R A B]\n  [inst_11 : IsScalarTower A B M'] (d : Derivation R B M') (x : B) (p : Polynomial A),\n  d ((Polynomial.aeval x) p) =\n    (PolynomialModule.eval x) ((Derivation.compAlge..."
    },
    {
      "name": "Derivation.leibniz_pow",
      "module_name": "Mathlib.RingTheory.Derivation.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_2} {M : Type u_4} [inst : CommSemiring R] [inst_1 : CommSemiring A]\n  [inst_2 : AddCommMonoid M] [inst_3 : Algebra R A] [inst_4 : Module A M] [inst_5 : Module R M] (D : Derivation R A M)\n  (a : A) (n : ℕ), D (a ^ n) = n • a ^ (n - 1) • D a"
    },
    {
      "name": "DividedPowers.mul_dpow",
      "module_name": "Mathlib.RingTheory.DividedPowers.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} [inst : CommSemiring A] {I : Ideal A} (self : DividedPowers I) {m n : ℕ} {x : A},\n  x ∈ I → self.dpow m x * self.dpow n x = ↑((m + n).choose m) * self.dpow (m + n) x"
    },
    {
      "name": "DividedPowers.prod_dpow",
      "module_name": "Mathlib.RingTheory.DividedPowers.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} [inst : CommSemiring A] {I : Ideal A} {a : A} (hI : DividedPowers I) {ι : Type u_2} {s : Finset ι}\n  {n : ι → ℕ}, a ∈ I → ∏ i ∈ s, hI.dpow (n i) a = ↑(Nat.multinomial s n) * hI.dpow (s.sum n) a"
    },
    {
      "name": "Differential.coeff_mapCoeffs",
      "module_name": "Mathlib.RingTheory.Derivation.MapCoeffs",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} [inst : CommRing A] [inst_1 : Differential A] (p : Polynomial A) (i : ℕ),\n  (Differential.mapCoeffs p).coeff i = (p.coeff i)′"
    },
    {
      "name": "PowerSeries.coeff_divXPowOrder",
      "module_name": "Mathlib.RingTheory.PowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {f : PowerSeries R} {n : ℕ},\n  (PowerSeries.coeff n) f.divXPowOrder = (PowerSeries.coeff (n + f.order.toNat)) f"
    },
    {
      "name": "Derivation.leibniz_zpow",
      "module_name": "Mathlib.RingTheory.Derivation.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {M : Type u_3} [inst_1 : AddCommGroup M] [inst_2 : Module R M] {K : Type u_4}\n  [inst_3 : Field K] [inst_4 : Module K M] [inst_5 : Algebra R K] (D : Derivation R K M) (a : K) (n : ℤ),\n  D (a ^ n) = n • a ^ (n - 1) • D a"
    }
  ]
}

